using System;using System.IO;using System.Threading.Tasks;using System.Windows;using ReFix.Shared;
namespace ReFix.Tests{static class MiniIconsRegressionTests{
 internal static void Run(Action<string,bool> report){report("capture guard recognizes Windows capture hosts only",CaptureVisibility.IsCaptureProcess("SnippingTool")&&CaptureVisibility.IsCaptureProcess("screenclippinghost")&&CaptureVisibility.IsCaptureProcess("ScreenSketch")&&!CaptureVisibility.IsCaptureProcess("explorer")&&!CaptureVisibility.IsCaptureProcess("Discord")&&!CaptureVisibility.IsCaptureProcess(null));var legacy=new MiniIconsConfig{SchemaVersion=1,IconSize=24,Columns=5};legacy.Normalize();report("legacy mini default layout migrates to compact grid",legacy.SchemaVersion==2&&legacy.IconSize==16&&legacy.Columns==2);var custom=new MiniIconsConfig{SchemaVersion=1,IconSize=28,Columns=3};custom.Normalize();report("compact layout migration preserves custom icon sizes",custom.IconSize==28&&custom.Columns==3);var monitor=new Rect(-1920,-200,1920,1080);foreach(TaskMenuEdge side in Enum.GetValues(typeof(TaskMenuEdge))){Rect work=monitor;switch(side){case TaskMenuEdge.Left:work=new Rect(monitor.Left+48,monitor.Top,monitor.Width-48,monitor.Height);break;case TaskMenuEdge.Top:work=new Rect(monitor.Left,monitor.Top+48,monitor.Width,monitor.Height-48);break;case TaskMenuEdge.Right:work=new Rect(monitor.Left,monitor.Top,monitor.Width-48,monitor.Height);break;case TaskMenuEdge.Bottom:work=new Rect(monitor.Left,monitor.Top,monitor.Width,monitor.Height-48);break;}var edge=MiniIconsGeometry.Edge(monitor,work,1.5);var popup=MiniIconsGeometry.Popup(monitor,work,edge,new Size(300,190),8);report("mini-icons edge and popup follow taskbar on "+side,MiniIconsGeometry.TaskbarSide(monitor,work)==side&&work.Contains(edge)&&work.Contains(popup));}
  string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"mini-compat-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"controls.json"),"{\"Bindings\":{\"hub.toggle\":\"Ctrl+Alt+I\"}}");using(var controls=new ControlsStore(root))report("new default hotkey preserves older user assignments",controls.Current.Get("hub.toggle")=="Ctrl+Alt+I"&&controls.Current.Get("mini-icons.toggle")=="");
   var stress=Task.Run(delegate{for(int i=0;i<25;i++)using(var store=new ControlsStore(Path.Combine(root,"stress"))){store.Save(store.Current);store.ResetDefaults();}});bool complete=stress.Wait(5000);report("rapid settings writes and disposal do not deadlock watcher callbacks",complete);
  }finally{if(Directory.Exists(root))Directory.Delete(root,true);}
 }
}}
